import React, {useState, useCallback} from "react";
import {Card, type PiCardProps} from "@pihanga2/core";
import {cn} from "@/lib/utils";
import {FormContext, type FormContextValue} from "./form.context";
import type {PiFormEvents, PiFormProps} from "./form.types";

export const FormComponent = (
  props: PiCardProps<PiFormProps, PiFormEvents>,
): React.ReactNode => {
  const {
    id,
    content = [],
    initialValues = {},
    submitLabel = "Submit",
    className,
    cardName,
    onSubmitted,
  } = props;

  const [formData, setFormData] = useState<Record<string, unknown>>(() => ({
    ...initialValues,
  }));
  const [errors, setErrors] = useState<Record<string, string>>({});

  const handleChange = useCallback((fieldName: string, value: unknown) => {
    setFormData((prev) => ({...prev, [fieldName]: value}));
    // Clear validation error when the user modifies the field
    setErrors((prev) => {
      if (!prev[fieldName]) return prev;
      const next = {...prev};
      delete next[fieldName];
      return next;
    });
  }, []);

  const setError = useCallback((fieldName: string, error: string | null) => {
    setErrors((prev) => {
      if (error === null) {
        const next = {...prev};
        delete next[fieldName];
        return next;
      }
      return {...prev, [fieldName]: error};
    });
  }, []);

  const handleSubmit = useCallback(
    (e: React.FormEvent) => {
      e.preventDefault();
      onSubmitted({id, formData});
    },
    [id, formData, onSubmitted],
  );

  const contextValue: FormContextValue = {
    formData,
    errors,
    handleChange,
    setError,
    isInForm: true,
  };

  return (
    <FormContext.Provider value={contextValue}>
      <form
        onSubmit={handleSubmit}
        className={cn("flex flex-col gap-4", className)}
        data-pihanga={cardName}
      >
        {content.map((cref, idx) => (
          <Card key={idx} cardName={cref} parentCard={cardName} />
        ))}
        <button
          type="submit"
          className="inline-flex h-9 items-center justify-center rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground shadow transition-colors hover:bg-primary/90 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50"
        >
          {submitLabel}
        </button>
      </form>
    </FormContext.Provider>
  );
};

import React, {useContext} from "react";

/**
 * Shape of the data provided by FormContext.
 * When inside a <Form> card, isInForm is true and all fields are populated.
 * When outside (fallback), isInForm is false.
 */
export interface FormContextValue {
  formData: Record<string, unknown>;
  errors: Record<string, string>;
  handleChange: (fieldName: string, value: unknown) => void;
  setError: (fieldName: string, error: string | null) => void;
  isInForm: boolean;
}

const FALLBACK_CONTEXT: FormContextValue = {
  formData: {},
  errors: {},
  handleChange: () => {},
  setError: () => {},
  isInForm: false,
};

export const FormContext = React.createContext<FormContextValue | null>(null);

/**
 * Hook that reads the nearest FormContext.
 * Returns a fallback (isInForm=false) when called outside a <Form> card.
 *
 * Usage in field components:
 *   const form = useFormContext();
 *   const value = form.isInForm && name ? form.formData[name] ?? '' : propValue;
 */
export const useFormContext = (): FormContextValue => {
  const ctx = useContext(FormContext);
  return ctx ?? FALLBACK_CONTEXT;
};

import {
  createCardDeclaration,
  createOnAction,
  type PiCardRef,
  registerActions,
} from "@pihanga2/core";

export const PI_FORM_CARD = "pi/form";

export const Form = createCardDeclaration<PiFormProps, PiFormEvents>(
  PI_FORM_CARD,
);

export const PI_FORM_ACTION = registerActions(PI_FORM_CARD, ["submitted"]);

export const onPiFormSubmitted = createOnAction<PiFormSubmittedEvent>(
  PI_FORM_ACTION.SUBMITTED,
);

export type PiFormProps = {
  /**
   * Optional id passed through to events for identification.
   */
  id?: string;

  /**
   * Ordered list of field card refs to render inside the form.
   * Each card (e.g. TextField, Checkbox, FormSelect) will be rendered
   * in order and wrapped by a FormContext.Provider so they can read
   * and write shared form state.
   */
  content?: PiCardRef[];

  /**
   * Initial values for the form fields, keyed by field name.
   */
  initialValues?: Record<string, unknown>;

  /**
   * Label for the submit button.
   * @default "Submit"
   */
  submitLabel?: string;

  /**
   * Additional CSS classes for the <form> element.
   */
  className?: string;
};

export type PiFormSubmittedEvent = {
  id?: string;
  /** Snapshot of form state at the time of submission. */
  formData: Record<string, unknown>;
};

export type PiFormEvents = {
  onSubmitted: PiFormSubmittedEvent;
};

import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {FormComponent} from "./form.component";
import {PI_FORM_ACTION, PI_FORM_CARD} from "./form.types";

export * from "./form.types";
export * from "./form.context";

registerCardComponent({
  name: PI_FORM_CARD,
  component: FormComponent,
  events: actionTypesToEvents(PI_FORM_ACTION),
});
